import { NextRequest, NextResponse } from "next/server";
import { ZodError } from "zod";
import { requirePlatformOwner } from "@/core/server/platform-owner-guard";
import { updateLessonSchema } from "@/modules/courses/schemas/content.schemas";
import { updateCmsLesson } from "@/modules/cms/services/lesson-operations.service";

export async function PATCH(request: NextRequest, { params }: { params: Promise<{ lessonId: string }> }) {
  const guard = await requirePlatformOwner(request);
  if (!guard.ok) return NextResponse.json({ error: guard.error }, { status: guard.status });
  try {
    const lesson = await updateCmsLesson(guard.user.id, (await params).lessonId, updateLessonSchema.parse(await request.json()));
    return NextResponse.json({ data: lesson });
  } catch (error) {
    if (error instanceof ZodError) return NextResponse.json({ error: "Invalid lesson data.", issues: error.issues }, { status: 400 });
    return NextResponse.json({ error: error instanceof Error ? error.message : "Unable to update lesson." }, { status: 400 });
  }
}
